def get_final_brief(total_vulns_found: int, remediations: Dict[str, Any],
    ignored: Dict[str, Any], total_ignored: int, kwargs: Optional[Dict[str,
    Any]]=None) ->str:
    if not kwargs:
        kwargs = {}

    vuln_word = 'vulnerability' if total_vulns_found == 1 else 'vulnerabilities'
    ignored_word = 'vulnerability' if total_ignored == 1 else 'vulnerabilities'

    brief_text = f'{total_vulns_found} {vuln_word} reported'

    if total_ignored > 0:
        brief_text += f', {total_ignored} {ignored_word} ignored'

    if is_using_api_key() and remediations:
        remediations_count = get_remediations_count(remediations)
        rem_word = 'remediation' if remediations_count == 1 else 'remediations'
        brief_text += f', {remediations_count} {rem_word} recommended'

    brief_text += '.'

    return format_long_text(brief_text, start_line_decorator=' ', **kwargs)
